#### Module Federation Configuration

**Shell Application (Host)**:

```javascript
// webpack.config.js (Shell)
module.exports = {
  plugins: [
    new ModuleFederationPlugin({
      name: 'shell',
      remotes: {
        claimsMFE: 'claimsMFE@https://cdn.gainwell.com/mfe/claims/v1.2.3/remoteEntry.js',
        providerMFE: 'providerMFE@https://cdn.gainwell.com/mfe/provider/v2.0.1/remoteEntry.js',
        analyticsMFE: 'analyticsMFE@https://cdn.gainwell.com/mfe/analytics/v1.5.0/remoteEntry.js',
      },
      shared: {
        react: { singleton: true, requiredVersion: '^18.2.0' },
        'react-dom': { singleton: true, requiredVersion: '^18.2.0' },
        'react-router-dom': { singleton: true, requiredVersion: '^6.8.0' },
        '@gainwell/design-system': { singleton: true, requiredVersion: '^3.0.0' },
      },
    }),
  ],
};
```

**Claims Micro-Frontend (Remote)**:

```javascript
// webpack.config.js (Claims MFE)
module.exports = {
  plugins: [
    new ModuleFederationPlugin({
      name: 'claimsMFE',
      filename: 'remoteEntry.js',
      exposes: {
        './ClaimsApp': './src/ClaimsApp',
        './ClaimsRoutes': './src/routes',
      },
      shared: {
        react: { singleton: true, requiredVersion: '^18.2.0' },
        'react-dom': { singleton: true, requiredVersion: '^18.2.0' },
        'react-router-dom': { singleton: true, requiredVersion: '^6.8.0' },
        '@gainwell/design-system': { singleton: true, requiredVersion: '^3.0.0' },
      },
    }),
  ],
};
```

