#### Routing Integration

```typescript
// Shell Application - App.tsx
import { lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';

const ClaimsApp = lazy(() => import('claimsMFE/ClaimsApp'));
const ProviderApp = lazy(() => import('providerMFE/ProviderApp'));
const AnalyticsApp = lazy(() => import('analyticsMFE/AnalyticsApp'));

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Layout>
          <Suspense fallback={<LoadingSpinner />}>
            <Routes>
              <Route path="/claims/*" element={<ClaimsApp />} />
              <Route path="/provider/*" element={<ProviderApp />} />
              <Route path="/analytics/*" element={<AnalyticsApp />} />
            </Routes>
          </Suspense>
        </Layout>
      </AuthProvider>
    </BrowserRouter>
  );
}
```
